import React from "react";

function Projects() {
  const projects = [
    {
      title: "AI Voice Assistant",
      description: "Python-based assistant with speech-to-text, text-to-speech, and Gemini AI integration.",
      link: "https://github.com/Rahul-manjhi"
    },
    {
      title: "Full-Stack Todo App",
      description: "Spring Boot backend + JavaScript frontend for task management.",
      link: "https://github.com/Rahul-manjhi"
    },
    {
      title: "Employee Management System",
      description: "Node.js + Express + React app with JWT authentication.",
      link: "https://github.com/Rahul-manjhi"
    },
    {
      title: "Snake Game",
      description: "Classic game built for portfolio showcase.",
      link: "https://github.com/Rahul-manjhi"
    }
  ];

  return (
    <section id="projects" className="p-10 bg-gray-800 text-white">
      <h2 className="text-3xl font-bold mb-6">Projects</h2>
      <div className="grid md:grid-cols-2 gap-6">
        {projects.map((proj, index) => (
          <div key={index} className="p-6 bg-gray-700 rounded-lg shadow-lg hover:scale-105 transition">
            <h3 className="text-xl font-semibold">{proj.title}</h3>
            <p className="mt-2">{proj.description}</p>
            <a href={proj.link} target="_blank" rel="noopener noreferrer"
               className="mt-4 inline-block px-4 py-2 bg-blue-500 rounded hover:bg-blue-700">
              View on GitHub
            </a>
          </div>
        ))}
      </div>
    </section>
  );
}

export default Projects;
